+	if storage, bound, storageErr := mcpBoundRepoStorage(ctx, opts); storageErr == nil && bound {
+		boundKey = storage.Key
+	}
+	if !workspaceIncludesBoundRepo(manifest, boundKey, opts.Env.RepoRoot) {
