+	open := strings.Index(lower, "<title")
+	if open < 0 {
+		return ""
+	}
+	gt := strings.IndexByte(body[open:], '>')
+	if gt < 0 {
+		return ""
+	}
+	start := open + gt + 1
+	end := strings.Index(lower[start:], "</title>")
+	if end < 0 {
