{"id": "01M1VJF46E2H2A6WSB89Q7E4GJ", "trailId": "01M0DNQ8XCZ8B0FB39BG34XAGZ", "repositoryId": "01KWZ6252FA5XEMQJYDQ5ZX6RQ", "reviewId": "01M1VJF45J9G9VP79CXF7WVDSY", "codeVersionId": "01M1VHXQ4AK5T403HF6H7FMZVJ", "actorId": "agent:trail-review", "actorDisplayName": null, "body": "`runDistill`'s non-JSON branch only prints the summary counts and never surfaces `source.Warnings`, so a `--max-sessions`-capped run (used by the detached `setup` backfill, which runs without `--json`) silently drops the one warning that says the pass stopped short of the full corpus — the log looks like a complete run when sessions were deferred.", "severity": "medium", "confidence": 0.75, "status": "open", "statusReason": null, "statusActorId": null, "statusActorDisplayName": null, "statusChangedAt": null, "statusSource": null, "statusActorKind": null, "staleOutcome": "stale", "staleCheckedAt": "2026-09-06T16:02:16.444Z", "staleCheckedCodeVersionId": "01M1VQ9H62K4446TWXSA9WKR5Y", "clientId": "c430a5115842efdd5521c99a5bcd5fd8", "clientIdHash": "6f6babef7774b96cd585a0105d776ce516599d39cf75b9502471b7cb97442af2", "createdAt": "2026-09-06T14:37:56.814Z", "updatedAt": "2026-09-06T14:37:56.814Z", "location": {"id": "01M1VJF46EV4AD2CC48VMEFJZ7", "reviewCommentId": "01M1VJF46E2H2A6WSB89Q7E4GJ", "codeVersionId": "01M1VHXQ4AK5T403HF6H7FMZVJ", "granularity": "line", "filePath": "internal/cli/distill_cmd.go", "startLine": 710, "startColumn": null, "endLine": null, "endColumn": null, "selectedText": "	fmt.Fprintf(cmd.OutOrStdout(), "distilled %d facts (%d distilled, %d authored, %d superseded) across %d branch(es) from %d chunks; %d proposals queued for review\n",", "nearbyText": null, "language": null}}
{"id": "01M1VJF45VWN1JQ5PET37VCCX4", "trailId": "01M0DNQ8XCZ8B0FB39BG34XAGZ", "repositoryId": "01KWZ6252FA5XEMQJYDQ5ZX6RQ", "reviewId": "01M1VJF45J9G9VP79CXF7WVDSY", "codeVersionId": "01M1VHXQ4AK5T403HF6H7FMZVJ", "actorId": "agent:trail-review", "actorDisplayName": null, "body": "`--newest-first` (used by the production backfill/watch path) processes sessions most-recent-first while `byBranch[branch]` accumulates the running "existing" fact set in visitation order, but `reconcilePrompt()` still tells the agent "the candidate is newer/correct" unconditionally. In newest-first mode, once the newest session's facts are in `byBranch`, an older session's candidate is compared against them while still being told it's the newer one, so the agent can `supersede` a correct, newer fact with a stale, older candidate. `factmerge.ApplyActions` then marks the newer fact `StatusSuperseded` with nothing checking actual timestamps.", "severity": "high", "confidence": 0.82, "status": "open", "statusReason": null, "statusActorId": null, "statusActorDisplayName": null, "statusChangedAt": null, "statusSource": null, "statusActorKind": null, "staleOutcome": "stale", "staleCheckedAt": "2026-09-06T16:02:16.444Z", "staleCheckedCodeVersionId": "01M1VQ9H62K4446TWXSA9WKR5Y", "clientId": "daede3782da82c57aed6f5123f489ffc", "clientIdHash": "470d5be58c03ca38d692114d2304a1d6fd401bbeb8362524c3e761d904c12f72", "createdAt": "2026-09-06T14:37:56.795Z", "updatedAt": "2026-09-06T14:37:56.795Z", "location": {"id": "01M1VJF45V5Q75SXND3KV34JM7", "reviewCommentId": "01M1VJF45VWN1JQ5PET37VCCX4", "codeVersionId": "01M1VHXQ4AK5T403HF6H7FMZVJ", "granularity": "line", "filePath": "internal/cli/distill_cmd.go", "startLine": 793, "startColumn": null, "endLine": null, "endColumn": null, "selectedText": "	// reverses it for the backfill pass (see sortDistillSessions).", "nearbyText": null, "language": null}}

