+		hint := strings.TrimSpace(repo.LocalPathHint)
+		if hint == "" {
+			return mcpCrossRepoRefusal(tool, fmt.Sprintf("workspace %q member %q has no local path, so its location cannot be checked", manifest.Name, repo.RepoKey), boundKey)
