 got, err := rebaseFactsOntoDisk(dir,"main",cloneDistillFacts(baseline),baseline,false)
 if err != nil { t.Fatal(err) }
 if got[0].Status != factStatusActive { t.Fatal("lost concurrent reactivation") }
}
''')
